    const url=URL.createObjectURL(new Blob([html],{type:"text/html;charset=utf-8"})); const a=document.createElement("a");a.href=url;a.download="Plano_de_Negocios.html";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
